const slides=[...document.querySelectorAll('.slide')];const dots=[...document.querySelectorAll('.slider-dots button')];let current=0;let timer;function showSlide(index){current=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('is-active',i===current));dots.forEach((dot,i)=>dot.classList.toggle('is-active',i===current))}function startSlider(){clearInterval(timer);timer=setInterval(()=>showSlide(current+1),6500)}document.querySelector('.next').addEventListener('click',()=>{showSlide(current+1);startSlider()});document.querySelector('.prev').addEventListener('click',()=>{showSlide(current-1);startSlider()});dots.forEach((dot,i)=>dot.addEventListener('click',()=>{showSlide(i);startSlider()}));startSlider();

const menuButton=document.querySelector('.menu-button');const nav=document.querySelector('#main-nav');menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});nav.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')});

const sections=[...document.querySelectorAll('main section[id],header[id]')];const navLinks=[...document.querySelectorAll('#main-nav a')];const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){navLinks.forEach(link=>link.classList.toggle('active',link.getAttribute('href')===`#${entry.target.id}`))}})},{rootMargin:'-30% 0px -60%',threshold:0});sections.forEach(section=>observer.observe(section));

document.querySelector('#quote-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const message=`السلام عليكم شركة آر آر آر للتجارة،\nالاسم/المؤسسة: ${data.get('name')}\nفئة المواد: ${data.get('product')}\nتفاصيل الطلب: ${data.get('details')}`;window.open(`https://wa.me/966554610355?text=${encodeURIComponent(message)}`,'_blank','noopener')});document.querySelector('#year').textContent=new Date().getFullYear();
